package vn.edu.hcmute.example3; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="products") public class Product {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(length=2000) private String description; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; private String imageUrl; @ManyToOne(fetch=FetchType.LAZY,optional=false) private AppUser owner; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); protected Product(){} public Product(String name,String description,BigDecimal price,String imageUrl,AppUser owner){this.name=name;this.description=description;this.price=price;this.imageUrl=imageUrl;this.owner=owner;} public Long getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public BigDecimal getPrice(){return price;} public String getImageUrl(){return imageUrl;} public AppUser getOwner(){return owner;} public void update(String n,String d,BigDecimal p,String i){name=n;description=d;price=p;imageUrl=i;} }
